export class CreateTenantDto {
  @IsString()
  @MinLength(2)
  @MaxLength(255)
  @IsNotEmpty()
  @Transform(({ value }) => value?.trim())
  name!: string;

  @IsOptional()
  @IsString()
  @MinLength(3)
  @MaxLength(50)
  @Matches(/^[a-z0-9][a-z0-9-]*[a-z0-9]$/, {
    message:
      'Slug must be lowercase alphanumeric with hyphens, not starting or ending with hyphen',
  })
  @Transform(({ value }) => value?.toLowerCase().trim())
  slug?: string;

  @IsOptional()
  @IsString()
  @MaxLength(500)
  @Transform(({ value }) => value?.trim())
  description?: string;

  @IsOptional()
  @IsString()
  @MaxLength(255)
  @Matches(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$/, {
    message: 'Invalid domain format',
  })
  @Transform(({ value }) => value?.toLowerCase().trim())
  domain?: string;

  @IsOptional()
  @IsEmail()
  @MaxLength(255)
  contactEmail?: string;

  @IsOptional()
  @IsString()
  @MaxLength(50)
  contactPhone?: string;

  @IsOptional()
  @IsEnum(TenantPlan)
  tier?: TenantTier;

  @IsOptional()
  @ValidateNested()
  @Type(() => TenantContactDto)
  primaryContact?: TenantContactDto;

  @IsOptional()
  @ValidateNested()
  @Type(() => TenantContactDto)
  billingContact?: TenantContactDto;

  @IsOptional()
  @IsEmail()
  @MaxLength(255)
  billingEmail?: string;

  @IsOptional()
  @IsString()
  @Matches(/^[A-Z]{2}$/, {
    message: 'Country must be a valid ISO 3166-1 alpha-2 code (e.g., US, GB, AU)',
  })
  @Transform(({ value }) => value?.toUpperCase().trim())
  country?: string;

  @IsOptional()
  @IsString()
  @MaxLength(100)
  region?: string;

  @IsOptional()
  @IsNumber()
  @Min(1)
  trialDays?: number;

  @IsOptional()
  @IsNumber()
  @Min(1)
  maxUsers?: number;

  @IsOptional()
  @IsNumber()
  @Min(-1)
  maxStorage?: number;

  @IsOptional()
  @ValidateNested()
  @Type(() => TenantLimitsDto)
  limits?: TenantLimitsDto;

  @IsOptional()
  @ValidateNested()
  @Type(() => TenantSettingsDto)
  settings?: TenantSettingsDto;

  @IsOptional()
  @IsEnum(TenantPlan)
  plan?: TenantPlan;

  /**
   * Module IDs to assign to the tenant during creation
   * Super Admin selects which modules the tenant will have access to
   */
  @IsOptional()
  @IsArray()
  @IsUUID('4', { each: true })
  moduleIds?: string[];

  /**
   * Optional quantity configuration per module
   * Allows specifying users, farms, ponds etc. per module for pricing
   */
  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => ModuleQuantityDto)
  moduleQuantities?: ModuleQuantityDto[];

  /**
   * Billing cycle preference
   */
  @IsOptional()
  @IsIn(BILLING_CYCLES)
  billingCycle?: BillingCycle;

  @IsOptional()
  @IsUUID('4')
  catalogVersionId?: string;

  @IsOptional()
  @IsUUID('4')
  quoteId?: string;

  @IsOptional()
  @IsUUID('4')
  customPlanId?: string;
}

export enum TenantProvisioningState {
  QUEUED = 'QUEUED',
  RESERVING = 'RESERVING',
  RUNNING = 'RUNNING',
  SUCCEEDED = 'SUCCEEDED',
  FAILED = 'FAILED',
}

export class TenantProvisioningStepDto {
  name!: string;
  state!: TenantProvisioningState;
  attempts!: number;
  lastError?: string;
  startedAt?: Date;
  completedAt?: Date;
}

export class CreateTenantAcceptedResponse {
  /**
   * Operation state. Public clients must make decisions from this field only.
   */
  status!: TenantProvisioningState;

  /**
   * Tenant lifecycle status from the approved admin projection, when known.
   */
  tenantStatus?: TenantStatus;

  /**
   * Canonical relative polling URL. Legacy /api, /api/v1, and /v1 aliases are
   * intentionally not part of the contract.
   */
  statusUrl!: string;

  retryAfterMs!: number;
  availableActions!: string[];

  /**
   * Per-step provisioning detail, ordered by step order.
   *
   * WHY: `status` alone collapses a twelve-step saga into one word. An operator
   * polling a FAILED run could see THAT it failed but never WHICH step failed or
   * WHY — the workflow already read the step rows on every poll and discarded
   * them. Always an array (never undefined) so clients render progress without
   * a presence check.
   */
  steps!: TenantProvisioningStepDto[];
}

